#include <bits/stdc++.h>
using namespace std;

using int64 = long long;
const int64 MOD = 1000000007LL;

int64 modpow(int64 base, int64 exp, int64 mod) {
    int64 result = 1;
    base %= mod;
    while (exp > 0) {
        if (exp & 1) result = (result * base) % mod;
        base = (base * base) % mod;
        exp >>= 1;
    }
    return result;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    int t = 1;
    cin >> t;

    while (t--) {
        int64 n, k;
        cin >> n >> k;
        int64 ans = modpow(n, k, MOD);
        cout << ans << '\n';
    }

    return 0;
}

